package com.realmsoffate.toolkit.ui.characters;
import com.realmsoffate.toolkit.data.ClassDataService;import com.realmsoffate.toolkit.project.ModProject;import com.realmsoffate.toolkit.ui.ToolkitColors;import javax.swing.*;import java.awt.*;import java.io.IOException;
public class CharactersPanel extends JPanel{public interface Listener{void onNewClass();void onOpenClass(ClassDataService.Entry e);}public CharactersPanel(ModProject p,ClassDataService s,Listener l){setLayout(new BorderLayout());setBorder(BorderFactory.createEmptyBorder(24,24,24,24));setBackground(ToolkitColors.BACKGROUND);JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JLabel h=new JLabel("Characters & Classes");h.setFont(h.getFont().deriveFont(Font.BOLD,26f));h.setForeground(ToolkitColors.TEXT_PRIMARY);JButton add=new JButton("+ New Class");add.addActionListener(e->l.onNewClass());top.add(h,BorderLayout.WEST);top.add(add,BorderLayout.EAST);add(top,BorderLayout.NORTH);JPanel list=new JPanel();list.setOpaque(false);list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));try{for(ClassDataService.Entry x:s.list(p)){JButton b=new JButton(x.getName());b.setHorizontalAlignment(SwingConstants.LEFT);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,42));b.addActionListener(e->l.onOpenClass(x));list.add(b);list.add(Box.createVerticalStrut(6));}}catch(IOException ex){list.add(new JLabel(ex.getMessage()));}JScrollPane sp=new JScrollPane(list);sp.setBorder(null);add(sp,BorderLayout.CENTER);}}
